TWComponent.script:
try{
	var input = JSON.parse(tw.local.data);

	tw.local.fromCurrency = input.ccFrom;
	tw.local.toCurrency = input.ccTo;
	tw.local.rateSubType = input.sType;
	tw.local.rateType = input.type;
} catch (err) {
	tw.local.errorMSG = err.message;
	throw new Error(tw.local.errorMSG);
	
}

